$pass=0;$fail=0;function check(string $n,bool $ok):void{global $pass,$fail;echo ($ok?'PASS':'FAIL').": $n\n";if($ok)$pass++;else$fail++;}
final class TestClock implements Clock{public function __construct(public DateTimeImmutable $t){}public function now():DateTimeImmutable{return $this->t;}}
function pdo():PDO{$p=new PDO('sqlite::memory:');$p->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$p->exec(file_get_contents(__DIR__.'/../database/schema.sql'));$p->exec("INSERT INTO tenants VALUES ('H1','Uno',1),('H2','Dos',1),('H3','Cerrado',0)");return $p;}
function controller($kind,TestClock $clock,&$ur=null,&$sr=null):AuthController{
 if($kind==='pdo'){$p=pdo();$t=new PdoTenantRepository($p);$ur=new PdoUserRepository($p);$sr=new PdoSessionRepository($p);}else{$t=new InMemoryTenantRepository(['H1'=>true,'H2'=>true,'H3'=>false]);$ur=new InMemoryUserRepository();$sr=new InMemorySessionRepository();}
 $h=new BcryptHasher(4);$ids=new RandomTokens();return new AuthController(new RegisterUser($t,$ur,$h,$ids,$clock),new Authenticate($ur,$sr,$h,$ids,$clock),new RevokeSession($sr,$clock));}
foreach(['pdo','memory'] as $kind){$clock=new TestClock(new DateTimeImmutable('2026-10-27 08:00:00'));$c=controller($kind,$clock,$ur,$sr);$label=strtoupper($kind);
