}
$clock=new TestClock(new DateTimeImmutable('2026-10-27 08:00:00'));$ur=null;$sr=null;$c=controller('memory',$clock,$ur,$sr);$mvc=new AuthMvcController($c);$router=new Router($mvc);$rr=$router->dispatch(new Request('POST','/tenants/H1/users',['email'=>'m@h.gt','password'=>'ClaveSegura2026']));check('MVC router registra 201',$rr->status===201);$ll=$router->dispatch(new Request('POST','/tenants/H1/sessions',['email'=>'m@h.gt','password'=>'ClaveSegura2026']));check('MVC router autentica 200',$ll->status===200);$token=$ll->body['token'];check('MVC router revoca 204',$router->dispatch(new Request('DELETE','/sessions',[],['Authorization'=>'Bearer '.$token]))->status===204);check('MVC logout token revocado 401',$router->dispatch(new Request('DELETE','/sessions',[],['Authorization'=>'Bearer '.$token]))->status===401);check('MVC ruta desconocida 404',$router->dispatch(new Request('GET','/missing'))->status===404);check('MVC método incorrecto 405',$router->dispatch(new Request('GET','/tenants/H1/users'))->status===405);check('JsonView genera JSON válido',json_decode((new JsonView())->render(new \Auth\Presentation\Response(200,['ok'=>true])),true)['ok']===true);
$src=file_get_contents(__DIR__.'/../src/Presentation/Mvc.php');check('MVC no contiene SQL ni PDO',!preg_match('/\bPDO\b|SELECT|INSERT|UPDATE|DELETE\s+FROM/',$src));
$clock=new TestClock(new DateTimeImmutable('2026-10-27 08:00:00'));$ur=new InMemoryUserRepository();$sr=new InMemorySessionRepository();$c=controller('memory',$clock,$dummy,$dummyS);$ur->failNext();$c=new AuthController(new RegisterUser(new InMemoryTenantRepository(),$ur,new BcryptHasher(4),new RandomTokens(),$clock),new Authenticate($ur,$sr,new BcryptHasher(4),new RandomTokens(),$clock),new RevokeSession($sr,$clock));check('InMemory failNext user en alta 503',$c->register('H1','f@h.gt','ClaveSegura2026')['status']===503);$c->register('H1','f@h.gt','ClaveSegura2026');$c->login('H1','f@h.gt','ClaveSegura2026');$sr->failNext();check('InMemory failNext sesión en login 503',$c->login('H1','f@h.gt','ClaveSegura2026')['status']===503);
